import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 5500;
    static final long INF = 1000000007L;
    static int n, m, k, c, d;
    static int u, v, max_flow, s = MAX - 2, t = MAX - 1, flow = 0, parent[] = new int[MAX];
    static long total_cost = 0, dist[] = new long[MAX];
    static PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingLong(p -> p.dist));
    static List<Edge>[] graph = new ArrayList[MAX];

    static class Edge {
        int v, c, index, capacity;
        Edge(int v, int c, int index, int capacity) {
            this.v = v;
            this.c = c;
            this.index = index;
            this.capacity = capacity;
        }
    }

    static class Pair {
        long dist;
        int node;
        Pair(long dist, int node) {
            this.dist = dist;
            this.node = node;
        }
    }

    static void addEdge(int u, int v, int cost, int cap) {
        int sizeU = graph[u].size();
        int sizeV = graph[v].size();
        graph[u].add(new Edge(v, cost, sizeV, cap));
        graph[v].add(new Edge(u, -cost, sizeU, 0));
    }

    static void computeShortestPath() {
        Arrays.fill(dist, INF);
        parent = new int[MAX];
        Arrays.fill(parent, -1);
        dist[s] = 0;
        pq.clear();
        pq.add(new Pair(0, s));
        while (!pq.isEmpty()) {
            Pair current = pq.poll();
            long currDist = current.dist;
            int node = current.node;
            if (currDist > dist[node]) continue;
            for (Edge edge : graph[node]) {
                if (edge.capacity > 0 && dist[edge.v] > currDist + edge.c) {
                    parent[edge.v] = edge.index;
                    dist[edge.v] = currDist + edge.c;
                    pq.add(new Pair(dist[edge.v], edge.v));
                }
            }
        }
    }

    static void augmentFlow() {
        int flowIncrement = k;
        int v = t;
        while (v != s) {
            int u = graph[v].get(parent[v]).v;
            int ind = graph[v].get(parent[v]).index;
            flowIncrement = Math.min(flowIncrement, graph[u].get(ind).capacity);
            v = u;
        }
        flow += flowIncrement;
        total_cost += (long) flowIncrement * dist[t];
        v = t;
        while (v != s) {
            int u = graph[v].get(parent[v]).v;
            int ind = graph[v].get(parent[v]).index;
            graph[v].get(parent[v]).capacity += flowIncrement;
            graph[u].get(ind).capacity -= flowIncrement;
            v = u;
        }
    }

    static int nodeId(int u, int t) {
        return u + t * n;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());
        max_flow = n + k;

        for (int i = 0; i < MAX; i++) {
            graph[i] = new ArrayList<>();
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            u = Integer.parseInt(st.nextToken());
            addEdge(s, nodeId(u, 0), 0, 1);
        }

        for (int i = 0; i <= max_flow; i++) {
            addEdge(nodeId(1, i), t, c * i, k);
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < max_flow; j++) {
                addEdge(nodeId(i, j), nodeId(i, j + 1), 0, k);
            }
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            u = Integer.parseInt(st.nextToken());
            v = Integer.parseInt(st.nextToken());
            for (int j = 0; j < k; j++) {
                for (int l = 0; l < max_flow; l++) {
                    addEdge(nodeId(u, l), nodeId(v, l + 1), d * (2 * j + 1), 1);
                    addEdge(nodeId(v, l), nodeId(u, l + 1), d * (2 * j + 1), 1);
                }
            }
        }

        while (flow < k) {
            computeShortestPath();
            augmentFlow();
        }

        System.out.println(total_cost);
    }
}
